src/components/InlineOrderBanner.astro.utf8Content:
---
import {site} from '../config/site';
---
<aside class="inline-order-banner" data-order-banner="inline" aria-label={`${site.brand} ${site.region} 주문 안내`}>
  <div class="inline-order-copy">
    <strong>{site.brand}와 함께 마음을 전할 꽃을 골라 보세요</strong>
    <span>전화 {site.phoneOrderHours} · 온라인 {site.onlineOrderHours} 접수</span>
    <small>어떤 꽃이 좋을지 고민되시면 보내는 목적과 예산부터 편하게 말씀해 주세요. 상담시간과 실제 전달시간은 다를 수 있어요. 원하시는 전달 일정은 주문할 때 함께 확인해 주세요.</small>
  </div>
  <div class="inline-order-actions">
    <a class="inline-order-phone" href={site.phoneHref}>전화 상담 {site.phone}</a>
    <a class="inline-order-online" href={site.orderUrl}>{site.brand} 온라인 주문</a>
  </div>
</aside>
<style>
  .inline-order-banner{margin:32px 0;padding:24px;border:1px solid #ddc5d6;border-radius:16px;background:#fff6fa;box-shadow:0 8px 24px rgba(58,33,79,.04)}
  .inline-order-copy{display:flex;flex-direction:column;gap:8px}
  .inline-order-copy strong{font-size:20px;line-height:1.45;color:#3a214f}
  .inline-order-copy span{font-size:15px;line-height:1.65;color:#554c57}
  .inline-order-copy small{font-size:13px;line-height:1.7;color:#655568}
  .inline-order-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
  .inline-order-actions a{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:11px 18px;border:1px solid #3a214f;border-radius:11px;font-size:15px;font-weight:800;line-height:1.5;text-decoration:none;overflow-wrap:anywhere}
  .inline-order-actions .inline-order-phone{background:#fff;color:#3a214f}
  .inline-order-actions .inline-order-online{background:#3a214f;color:#fff}
  @media(max-width:600px){.inline-order-banner{padding:20px 16px}.inline-order-actions{display:grid;grid-template-columns:1fr}.inline-order-actions a{width:100%}}
</style>

src/components/InlineText.astro.utf8Content:
---
import {inlineTokens} from '../lib/content.mjs';
const {text=''}=Astro.props;
---
{inlineTokens(text).map(token => token.type === 'strong' ? <strong>{token.text}</strong> : token.type === 'link' && token.href ? <a href={token.href}>{token.text}</a> : <Fragment>{token.text}</Fragment>)}

src/components/MarkdownContent.astro.utf8Content:
---
import {displayMarkdownBlocks} from '../lib/content.mjs';
import InlineText from './InlineText.astro';
const blocks=displayMarkdownBlocks(Astro.props.content || '', Astro.props.firstAnswer);
---
<div class="content-card markdown-content">{blocks.map(block => block.type === 'h2' ? <h2><InlineText text={block.text}/></h2> : block.type === 'h3' ? <h3><InlineText text={block.text}/></h3> : block.type === 'li' ? <ul><li><InlineText text={block.text}/></li></ul> : <p><InlineText text={block.text}/></p>)}</div>

src/components/ProductCards.astro.utf8Content:
---
import {site} from '../config/site';
const {products=[]}=Astro.props;
---
<div class="product-grid">{products.map((p:any)=><article class="product-card" data-product-family={p.family} data-product-key={p.key}><img src={p.img} alt={p.name} loading="lazy" width="420" height="420"/><div><h3>{p.name}</h3><strong>{p.price.toLocaleString()}원</strong><p>{p.desc}</p>{p.family==='congrats' && <p class="product-notice">사진 속 리본 문구는 예시입니다. 개업·행사 문구는 주문 시 확인해 주세요</p>}<a href={p.orderUrl || site.orderUrl}>상품 확인·주문 →</a></div></article>)}</div>
<p class="product-notice">{site.productVariationNotice} {site.deliveryNotice}</p>

src/components/RegionDirectory.astro.utf8Content:
---
import {site} from '../config/site';
import {groupsFor,coverage as sourceCoverage} from '../lib/regional-runtime.mjs';
import InlineOrderBanner from './InlineOrderBanner.astro';
const {pages}=Astro.props;
type Representative={pageKey:string;unitKeys:string[]};
type District={key:string;name:string;sourceUrl:string};
type RegionEntry={representative:Representative;page:{url:string;primaryKeyword:string;cardSummary:string}};
type RegionGroup=District & {items:RegionEntry[]};
type Coverage={districts:District[];units:{unitKey:string;name:string}[];administrativeCrosswalk:{aliasKey:string;name:string;districtKey:string;relations:{unitKey:string;scope:string}[]}[]};
const coverage=sourceCoverage as Coverage;
const districts=groupsFor(pages) as RegionGroup[];
const published=new Map<string,RegionEntry>(districts.flatMap(d=>d.items).flatMap(entry=>entry.representative.unitKeys.map(key=>[key,entry] as [string,RegionEntry])));
---
<section class="category-hero">
  <span class="eyebrow">{site.brand} {site.region}</span>
  <h1>{site.region} 지역별 꽃배달 안내</h1>
  <p>안양에서 위로와 축하를 전할 꽃을 살펴보세요. 7개 법정동별 안내에서 상품과 보내는 상황을 찾아보실 수 있습니다. 명학동·병목안동 등 행정동 이름으로도 아래에서 찾을 수 있어요.</p>
  <div class="actions"><a class="btn primary" href={site.phoneHref}>전화 상담·주문</a><a class="btn dark" href={site.orderUrl}>온라인 주문</a></div>
</section>
<nav class="actions" aria-label="구별 지역 안내">{districts.map(d=><a class="btn light" href={`#${d.key}`}>{d.name}</a>)}</nav>
{districts.map((district,index)=><section id={district.key} data-region-district={district.key}>
  <div class="section-title"><h2>{district.name}</h2></div>
  <div class="card-grid big">{district.items.map(({representative,page})=><a class="page-card" href={page.url} data-region-unit={representative.unitKeys.join('|')}><strong>{page.primaryKeyword}</strong><span>{page.cardSummary}</span><em>주문 안내 보기 →</em></a>)}</div>
  {index===Math.floor((districts.length-1)/2) && <InlineOrderBanner/>}
  <details class="content-card"><summary>행정동 이름으로 찾기</summary>
    <p>행정동과 주소에 쓰이는 법정동은 범위가 다를 수 있습니다. ‘일부’로 표시한 관계는 동 전체를 뜻하지 않습니다.</p>
    <ul class="decision-list">{coverage.administrativeCrosswalk.filter(a=>a.districtKey===district.key).map(admin=><li data-administrative-unit={admin.aliasKey}><strong>{admin.name}</strong>: {admin.relations.map((relation,index)=>{
      const unit=coverage.units.find(unit=>unit.unitKey===relation.unitKey);
      const entry=published.get(relation.unitKey);
      if(!unit)throw new Error('Administrative relation lacks a legal unit');
      return <>{index>0?' · ':''}{entry ? <a href={entry.page.url}>{unit.name}</a> : <span>{unit.name}</span>}{relation.scope==='partial'?' 일부':''}</>;
    })}</li>)}</ul>
    <a href={district.sourceUrl} rel="nofollow">{district.name} 공식 관할 안내</a>
  </details>
</section>)}

src/config/site.ts.utf8Content:
import truth from '../data/business-truth.json';
import architecture from '../data/architecture.json';
import pages from '../data/pages.json';
import config from '../data/site-config.json';
const domain = (import.meta.env.SITE_URL || config.previewUrl).replace(/\/$/, '');
export const site = {
  brand: truth.brand, region: config.region, domain,
  indexable: import.meta.env.SITE_INDEXABLE === 'true' && config.productionApproved === true,
  phone: truth.phone, phoneHref: truth.phoneHref, orderUrl: truth.onlineOrderUrl,
  phoneOrderHours: truth.phoneOrderHours.replace('-', '~'), onlineOrderHours: truth.onlineOrderHours,
  orderHours: `전화 ${truth.phoneOrderHours.replace('-', '~')} · 온라인 ${truth.onlineOrderHours} 접수`,
  deliveryNotice: truth.deliveryNotice, productVariationNotice: truth.productVariationNotice,
  naverVerification: config.naverVerification || ''
};
const publishedPages = pages as {category:string}[];
export const groups = architecture.hubs.filter(h => publishedPages.some(p => p.category === h.category)).map(h => ({cat: h.category, label: h.label, url: h.url}));
export const serviceGroups = groups.filter(group => group.cat !== 'regions');
export const menuGroups = architecture.hubs.filter(h => publishedPages.filter(p => p.category === h.category).length >= 5).map(h => ({cat: h.category, label: h.label, url: h.url}));

