---
<BaseLayout title={`${site.region} ${group.label} 꽃배달 | ${site.brand}`} description={isRegional ? '안양의 지역별 근조·축하화환을 살펴보세요. 보내는 목적과 예산에 맞는 상품을 찾아 주문을 상담할 수 있습니다.' : guide!.intro} canonicalPath={group.url} noindex={items.length < 3} orderUrl={hero?.orderUrl || site.orderUrl} socialProduct={hero || products[0]}>
