tests/answer-opening.test.mjs.utf8Content:
import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import {displayMarkdownBlocks,markdownBlocks} from '../src/lib/content.mjs';

const answer='빈소와 상주 성함을 확인한 뒤 주문해 주세요.';
const rest='\n\n## 주문 정보\n\n[전화 주문](tel:18440644)\n\n- 공식 출처 확인';
test('drops only the identical plain first paragraph and keeps all later blocks',()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+rest,answer),markdownBlocks(rest));
});
test('keeps different text and treats a single time-range tilde as plain text',()=>{
  const different='배송지부터 확인해 주세요.';
  assert.deepEqual(displayMarkdownBlocks(different+rest,answer),markdownBlocks(different+rest));
  const hours='전화주문 08:00~23:00';
  assert.deepEqual(displayMarkdownBlocks(hours+rest,hours),markdownBlocks(rest));
});
test('keeps a later repetition even after dropping the first paragraph',()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+'\n\n'+answer+rest,answer),markdownBlocks(answer+rest));
});
test('compares existing renderer text exactly without whitespace or Unicode normalization',()=>{
  for(const first of [' '+answer,answer+' ',answer.replace('빈소와','빈소와  '),answer.replace('.','!')])
    assert.deepEqual(displayMarkdownBlocks(answer+rest,first),markdownBlocks(answer+rest));
  assert.deepEqual(displayMarkdownBlocks('가'+rest,'가'),markdownBlocks('가'+rest));
});
test('existing multiline paragraph rendering is retained before exact comparison',()=>{
  const text='빈소와 상주 성함을\n확인한 뒤 주문해 주세요.';
  assert.deepEqual(displayMarkdownBlocks(text+rest,answer),markdownBlocks(rest));
});
for(const value of [undefined,null,'','   ',42])test(`no valid first answer: ${String(value)}`,()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+rest,value),markdownBlocks(answer+rest));
});
for(const [label,lead] of Object.entries({
  'link':`[${answer}](https://fwith.co.kr)`,
  'strong':`**${answer}**`,
  'emphasis':`*${answer}*`,
  'underscore':`_${answer}_`,
  'strikethrough':`~~${answer}~~`,
  'inline code':'`'+answer+'`',
  'image':`![${answer}](/image.jpg)`,
  'raw tag':`<p>${answer}</p>`,
  'attributed paragraph':`<p class="intro">${answer}</p>`,
  'inline span':`<span>${answer}</span>`,
  'comment':answer+'<!-- keep -->',
  'leading comment':'<!-- keep -->\n'+answer,
  'heading':'## '+answer,
  'list':'- '+answer,
  'ordered list':'1. '+answer,
  'reference link':'['+answer+'][source]',
  'named entity':'&copy;',
  'numeric entity':'&#128;',
  'escaped ampersand':'&amp;',
  'unknown entity':'&uncertain;',
  'incomplete entity':'&amp',
}))test(`preserves ${label}, even if its raw spelling is the firstAnswer`,()=>{
  for(const firstAnswer of [lead,answer])
    assert.deepEqual(displayMarkdownBlocks(lead+rest,firstAnswer),markdownBlocks(lead+rest));
});
test('eligible frozen pages remove exactly one duplicate and other pages stay intact',()=>{
  const pages=JSON.parse(fs.readFileSync(new URL('../src/data/pages.json',import.meta.url)));
  const before=JSON.stringify(pages);
  for(const page of pages){
    const original=markdownBlocks(page.contentMarkdown);
    const first=original[0];
    const eligible=first?.type==='p' && first.text===page.firstAnswer && !/[<>&*_`\[\]]|~~/.test(first.text);
    assert.deepEqual(displayMarkdownBlocks(page.contentMarkdown,page.firstAnswer),eligible?original.slice(1):original);
  }
  assert.equal(JSON.stringify(pages),before);
});
test('component receives the independently retained hero answer without raw HTML or CSS changes',()=>{
  const detail=fs.readFileSync(new URL('../src/pages/[category]/[slug].astro',import.meta.url),'utf8');
  const component=fs.readFileSync(new URL('../src/components/MarkdownContent.astro',import.meta.url),'utf8');
  assert.match(detail,/<p>\{page.firstAnswer\}<\/p>/);
  assert.match(detail,/<MarkdownContent content=\{page.contentMarkdown\} firstAnswer=\{page.firstAnswer\}\/>/);
  assert.match(component,/displayMarkdownBlocks/);assert.doesNotMatch(component,/set:html|<style/);
});

tests/catalog.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import {productFamilies} from '../src/lib/catalog.mjs';

const family=(pageType,primaryKeyword,visualIntent='consultation',category='order')=>
  productFamilies({pageType,primaryKeyword,visualIntent,category});
test('funeral-only order promises show funeral products',()=>{
  assert.deepEqual(family('message-guide','예시지역 근조화환 리본 문구'),['funeral']);
  assert.deepEqual(family('price-guide','예시지역 근조화환 가격'),['funeral']);
});
test('congratulation-only order promises show congratulations products',()=>{
  assert.deepEqual(family('message-guide','예시지역 축하화환 리본 문구'),['congrats']);
  assert.deepEqual(family('price-guide','예시지역 축하화환 가격'),['congrats']);
});
test('broad wreath comparison can show both, gift and performance exclude wreaths',()=>{
  assert.deepEqual(family('message-guide','예시지역 화환 문구','wreath_message'),['funeral','congrats']);
  assert.deepEqual(family('price-guide','예시지역 근조·축하화환 가격','flower_price'),['funeral','congrats']);
  assert.throws(()=>family('price-guide','예시지역 근조·축하화환 가격','funeral_wreath'),/contradicts/);
  assert.deepEqual(family('hospital-visit','예시지역 병문안 꽃','consultation','gift'),['bouquet','basket']);
  assert.deepEqual(family('event-venue','예시지역 공연 축하꽃','performance_venue','event'),['bouquet']);
});

tests/copy-revision-20261011.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {selectProducts,productFamilies} from '../src/lib/catalog.mjs';

const text=p=>fs.readFileSync(new URL(p,import.meta.url),'utf8');
const read=p=>JSON.parse(text(p));
const pages=read('../src/data/pages.json'),copy=read('./fixtures/reviewed-copy.json'),products=read('../src/data/products.json');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a<b?-1:a>b?1:0)):x);
test('all reviewed customer fields are exact independently approved copy, with original route order',()=>{
 assert.equal(sha(text('./fixtures/reviewed-copy.json')),'ca5d7e630db6030597eafbe063732d44a1f2b77f5501464ac2e72d7cde855fe9');assert.equal(pages.length,14);
 const omit=new Set(['productCardLimit','productCardKeys','status','approvalVerified','snapshotId','snapshotHash']);
 assert.deepEqual(pages.map(p=>p.pageKey),copy.map(p=>p.pageKey));
 for(let i=0;i<pages.length;i++){
  const project=x=>Object.fromEntries(Object.entries(x).filter(([k])=>!omit.has(k)));
  assert.deepEqual(project(pages[i]),project(copy[i]));
 }
});
for(const page of pages)test(`integrated ${page.slug}: exact cards, current hash and all mirror metadata`,()=>{
 const expected=page.slug==='jinwi-myeon'?8:4;assert.equal(page.productCardLimit,expected);assert.equal(page.productCardKeys.length,expected);
 const selected=selectProducts(page,products,(page.productCardLimit===4||productFamilies(page).length>3?4:3));assert.deepEqual(selected.map(p=>p.key),page.productCardKeys);
 const omit=new Set(['approvalVerified','status','file','order','sourceMode','snapshotId','snapshotHash']);
 const hash=sha(canonical(Object.fromEntries(Object.entries(page).filter(([k])=>!omit.has(k)))));
 assert.equal(page.snapshotHash,hash);assert.equal(page.snapshotId,`direct-content-${page.slug}-${hash.slice(0,16)}`);
 for(const name of ['page-map','architecture','publish-manifest']){
  const row=read('../src/data/'+name+'.json').pages.find(p=>p.pageKey===page.pageKey);
  for(const key of ['snapshotHash','snapshotId','productCardLimit','productCardKeys','url'])assert.deepEqual(row[key],page[key]);
 }
 const m=read('../src/data/publish-manifest.json');assert.deepEqual(m.snapshotLedger[page.snapshotId],{pageKey:page.pageKey,snapshotHash:hash});
 const record=m.directRelease.contentHashes.find(p=>p.pageKey===page.pageKey);assert.equal(record.publicSourceSha256,hash);assert.equal(record.bodySha256,sha(page.contentMarkdown));
});

tests/direct-source.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {selectProducts} from '../src/lib/catalog.mjs';
const read=name=>JSON.parse(fs.readFileSync(new URL(`../src/data/${name}.json`,import.meta.url),'utf8'));
const sha=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a<b?-1:a>b?1:0)):x);
const slugs=['anyang-dong','seoksu-dong','bakdal-dong','bisan-dong','gwanyang-dong','pyeongchon-dong','hogye-dong'];
test('Anyang has seven distinct legal-unit pages and all 31 current administrative names',()=>{
 const pages=read('pages'),coverage=read('region-coverage');
 assert.deepEqual(pages.filter(p=>p.pageType==='regional-service').map(p=>p.slug),slugs);assert.equal(coverage.units.length,7);assert.equal(coverage.administrativeCrosswalk.length,31);
 assert.equal(new Set(coverage.administrativeCrosswalk.map(a=>a.aliasKey)).size,31);
 for(const name of ['명학동','병목안동','호현동','충훈동','인덕원동'])assert.ok(coverage.administrativeCrosswalk.some(a=>a.name===name));
 assert.equal(coverage.districts.length,2);
 assert.equal(coverage.representatives.length,7);
});
test('direct snapshot hashes bind the public content and all four page collections',()=>{
 const pages=read('pages'),manifest=read('publish-manifest');
 assert.equal(manifest.directRelease.sourceMode,'direct-git');assert.deepEqual(manifest.snapshotLedger,Object.fromEntries(pages.map(p=>[p.snapshotId,{pageKey:p.pageKey,snapshotHash:p.snapshotHash}])));
 for(const p of pages){
  const omit=new Set(['approvalVerified','status','file','order','sourceMode','snapshotId','snapshotHash']);
  const digest=sha(canonical(Object.fromEntries(Object.entries(p).filter(([k])=>!omit.has(k)))));
  assert.equal(p.snapshotHash,digest);assert.equal(p.snapshotId,`direct-content-${p.slug}-${digest.slice(0,16)}`);
  const row=manifest.directRelease.contentHashes.find(x=>x.pageKey===p.pageKey);
  assert.equal(row.publicSourceSha256,digest);assert.equal(row.bodySha256,sha(p.contentMarkdown));
  for(const c of [manifest,read('page-map'),read('architecture')])assert.equal(c.pages.find(x=>x.pageKey===p.pageKey).snapshotHash,digest);
 }
});
test('Anyang source contains no copied regional data or old external workflow IDs',()=>{
 for(const name of ['pages','page-map','architecture','publish-manifest','region-coverage','region-policy','site-config']){
  const text=JSON.stringify(read(name));assert.doesNotMatch(text,/평택|pyeongtaek|rec[A-Za-z0-9]{14}|app[A-Za-z0-9]{14}|tbl[A-Za-z0-9]{14}|queueRecordId|sourceIssueNumber/);
 }
});
test('public ownership proof is unique and distinct from previous city',()=>{
 const root=new URL('../public/',import.meta.url);
 const matches=fs.readdirSync(root).filter(n=>/^[0-9a-f]{32}\.txt$/.test(n));assert.equal(matches.length,1);
 assert.equal(fs.readFileSync(new URL(matches[0],root),'utf8').trim(),matches[0].slice(0,-4));
 assert.notEqual(matches[0],'708ecb57c729d9c61d08c73f117b9e03.txt');
});

test('the five approved additions preserve regional scope and index only supported hubs',()=>{
 const pages=read('pages'),manifest=read('publish-manifest'),architecture=read('architecture');
 const added=[['funeral','anyang-funeral-hall-wreath'],['funeral','sam-hospital-funeral-wreath'],['funeral','hallym-hospital-funeral-wreath'],['event','patiobella-wedding-wreath'],['event','partyum-anyang-wedding-wreath']];
 assert.equal(pages.length,14);assert.equal(manifest.directRelease.appendedCount,5);
 assert.deepEqual(pages.slice(0,12).filter(p=>p.pageType!=='regional-service').map(p=>[p.category,p.slug]).sort(),added.sort());
 for(const [category,slug] of added){
  const p=pages.find(p=>p.slug===slug);assert.equal(p.url,`/${category}/${slug}/`);assert.equal(p.assetSlot,'REAL_PROOF');
  assert.equal(p.productCardLimit,4);assert.equal(p.productCardKeys.length,4);
  assert.deepEqual(selectProducts(p,read('products'),p.productCardLimit).map(x=>x.key),p.productCardKeys);
  assert.ok(selectProducts(p,read('products'),p.productCardLimit).every(x=>x.family===(category==='funeral'?'funeral':'congrats')));
  assert.ok(pages.some(q=>q.pageType==='regional-service'&&q.relatedKeys.includes(p.pageKey)),`Missing local inbound link for ${slug}`);
  assert.ok(p.sources.length>0);
 }
 const indexableHubs=architecture.hubs.filter(h=>h.indexable).map(h=>h.url).sort();
 assert.deepEqual(indexableHubs,['/event/','/funeral/','/regions/']);
 const htmlHubs=architecture.hubs.filter(h=>h.children>0).map(h=>h.url).sort();
 assert.deepEqual(htmlHubs,['/business/','/event/','/funeral/','/regions/']);
 assert.equal(1+pages.length+indexableHubs.length,18);assert.equal(1+pages.length+htmlHubs.length,19);
});

